import { createServer } from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { readFile } from 'node:fs/promises';
import { join, extname } from 'node:path';

const port = Number(process.env.PORT || 8080);
const dbPath = process.env.DB_PATH || './workboard.sqlite';
const db = new DatabaseSync(dbPath);
db.exec(`CREATE TABLE IF NOT EXISTS projects (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS tasks (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1)),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);`);

const publicDir = new URL('./public/', import.meta.url);
const contentTypes = { '.html': 'text/html; charset=utf-8', '.js': 'text/javascript; charset=utf-8', '.css': 'text/css; charset=utf-8' };
const json = (res, status, data) => {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(data));
};

const server = createServer(async (req, res) => {
  const url = new URL(req.url, `http://${req.headers.host || 'localhost'}`);
  if (req.method === 'GET' && url.pathname === '/health') return json(res, 200, { status: 'ok' });
  const taskRoute = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks(?:\/(\d+))?$/);
  if (taskRoute) {
    const projectId = Number(taskRoute[1]);
    if (!db.prepare('SELECT id FROM projects WHERE id = ?').get(projectId)) return json(res, 404, { error: 'Project not found' });
    if (req.method === 'GET' && !taskRoute[2]) {
      return json(res, 200, db.prepare('SELECT id, project_id AS projectId, title, completed FROM tasks WHERE project_id = ? ORDER BY id').all(projectId));
    }
    let body;
    try {
      let raw = '';
      for await (const chunk of req) raw += chunk;
      body = JSON.parse(raw);
    } catch { return json(res, 400, { error: 'Invalid request' }); }
    if (req.method === 'POST' && !taskRoute[2]) {
      if (typeof body.title !== 'string' || !body.title.trim()) return json(res, 400, { error: 'Task title is required' });
      const title = body.title.trim();
      const result = db.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)').run(projectId, title);
      return json(res, 201, { id: Number(result.lastInsertRowid), projectId, title, completed: 0 });
    }
    if (req.method === 'PATCH' && taskRoute[2]) {
      if (typeof body.completed !== 'boolean') return json(res, 400, { error: 'Completion must be boolean' });
      const result = db.prepare('UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?').run(Number(body.completed), Number(taskRoute[2]), projectId);
      if (!result.changes) return json(res, 404, { error: 'Task not found' });
      return json(res, 200, { ok: true });
    }
    return json(res, 405, { error: 'Method not allowed' });
  }
  if (url.pathname === '/api/projects' && req.method === 'GET') {
    return json(res, 200, db.prepare('SELECT id, name FROM projects ORDER BY id').all());
  }
  if (url.pathname === '/api/projects' && req.method === 'POST') {
    let body = '';
    for await (const chunk of req) body += chunk;
    let name;
    try { name = JSON.parse(body).name; } catch { return json(res, 400, { error: 'Invalid request' }); }
    if (typeof name !== 'string' || !name.trim()) return json(res, 400, { error: 'Project name is required' });
    const result = db.prepare('INSERT INTO projects (name) VALUES (?)').run(name.trim());
    return json(res, 201, { id: Number(result.lastInsertRowid), name: name.trim() });
  }
  if (req.method === 'GET' && (url.pathname === '/' || /^\/projects\/\d+$/.test(url.pathname))) {
    try {
      const html = await readFile(new URL('index.html', publicDir));
      res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
      return res.end(html);
    } catch { return json(res, 500, { error: 'Application unavailable' }); }
  }
  if (req.method === 'GET' && url.pathname.startsWith('/assets/')) {
    const filename = url.pathname.slice('/assets/'.length);
    if (!['app.js', 'style.css'].includes(filename)) return json(res, 404, { error: 'Not found' });
    try {
      const data = await readFile(new URL(filename, publicDir));
      res.writeHead(200, { 'content-type': contentTypes[extname(filename)] });
      return res.end(data);
    } catch { return json(res, 404, { error: 'Not found' }); }
  }
  return json(res, 404, { error: 'Not found' });
});

server.listen(port, '0.0.0.0');

const app = document.querySelector('#app');

async function getProjects() {
  const response = await fetch('/api/projects');
  if (!response.ok) throw new Error('Unable to load projects');
  return response.json();
}

function element(tag, text, className) {
  const node = document.createElement(tag);
  if (text !== undefined) node.textContent = text;
  if (className) node.className = className;
  return node;
}

async function render() {
  app.replaceChildren();
  const match = location.pathname.match(/^\/projects\/(\d+)$/);
  if (match) {
    const projects = await getProjects();
    const project = projects.find(item => String(item.id) === match[1]);
    if (!project) {
      app.append(element('h1', 'Project not found'));
    } else {
      app.append(element('h1', project.name));
      const form = element('form');
      const label = element('label', 'Task title');
      label.htmlFor = 'task-title';
      const input = element('input');
      input.id = 'task-title';
      input.type = 'text';
      input.setAttribute('aria-label', 'Task title');
      const submit = element('button', 'Create task');
      submit.type = 'submit';
      const alert = element('p');
      alert.className = 'alert';
      alert.setAttribute('role', 'alert');
      alert.hidden = true;
      form.append(label, input, submit, alert);
      form.addEventListener('submit', async event => {
        event.preventDefault();
        const title = input.value.trim();
        if (!title) {
          alert.textContent = 'Task title is required';
          alert.hidden = false;
          input.focus();
          return;
        }
        submit.disabled = true;
        try {
          const response = await fetch(`/api/projects/${project.id}/tasks`, {
            method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ title })
          });
          if (!response.ok) throw new Error((await response.json()).error || 'Unable to create task');
          await render();
        } catch (error) {
          alert.textContent = error.message;
          alert.hidden = false;
        } finally { submit.disabled = false; }
      });
      app.append(form);
      const filterLabel = element('label', 'Task filter');
      filterLabel.htmlFor = 'task-filter';
      const filter = element('select');
      filter.id = 'task-filter';
      filter.setAttribute('aria-label', 'Task filter');
      for (const value of ['All', 'Open', 'Completed']) filter.append(element('option', value));
      app.append(filterLabel, filter);
      const taskList = element('section');
      taskList.setAttribute('aria-label', 'Tasks');
      const response = await fetch(`/api/projects/${project.id}/tasks`);
      if (!response.ok) throw new Error('Unable to load tasks');
      const tasks = await response.json();
      const displayTasks = () => {
        taskList.replaceChildren();
        for (const task of tasks) {
          if (filter.value === 'Open' && task.completed || filter.value === 'Completed' && !task.completed) continue;
          const row = element('article', undefined, 'task-row');
          row.dataset.testid = 'task-row';
          row.append(element('span', task.title));
          const checkbox = element('input');
          checkbox.type = 'checkbox';
          checkbox.checked = Boolean(task.completed);
          checkbox.setAttribute('aria-label', `Complete ${task.title}`);
          checkbox.addEventListener('change', async () => {
            checkbox.disabled = true;
            try {
              const update = await fetch(`/api/projects/${project.id}/tasks/${task.id}`, {
                method: 'PATCH', headers: { 'content-type': 'application/json' },
                body: JSON.stringify({ completed: checkbox.checked })
              });
              if (!update.ok) throw new Error('Unable to update task');
              task.completed = Number(checkbox.checked);
              displayTasks();
            } catch (error) {
              checkbox.checked = !checkbox.checked;
              alert.textContent = error.message;
              alert.hidden = false;
              checkbox.disabled = false;
            }
          });
          row.append(checkbox);
          taskList.append(row);
        }
      };
      filter.addEventListener('change', displayTasks);
      displayTasks();
      app.append(taskList);
    }
    const back = element('button', 'Projects');
    back.type = 'button';
    back.addEventListener('click', () => { location.href = '/'; });
    app.append(back);
    return;
  }

  app.append(element('h1', 'Workboard'));
  const form = element('form');
  const label = element('label', 'Project name');
  label.htmlFor = 'project-name';
  const input = element('input');
  input.id = 'project-name';
  input.name = 'name';
  input.type = 'text';
  input.setAttribute('aria-label', 'Project name');
  const submit = element('button', 'Create project');
  submit.type = 'submit';
  const alert = element('p');
  alert.className = 'alert';
  alert.setAttribute('role', 'alert');
  alert.hidden = true;
  form.append(label, input, submit, alert);
  form.addEventListener('submit', async event => {
    event.preventDefault();
    const name = input.value.trim();
    if (!name) {
      alert.textContent = 'Project name is required';
      alert.hidden = false;
      input.focus();
      return;
    }
    submit.disabled = true;
    try {
      const response = await fetch('/api/projects', {
        method: 'POST', headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ name })
      });
      if (!response.ok) throw new Error('Unable to create project');
      input.value = '';
      alert.hidden = true;
      await render();
    } catch (error) {
      alert.textContent = error.message;
      alert.hidden = false;
    } finally { submit.disabled = false; }
  });
  app.append(form);
  const list = element('section');
  list.setAttribute('aria-label', 'Projects');
  for (const project of await getProjects()) {
    const row = element('article', undefined, 'project-row');
    row.dataset.testid = 'project-row';
    row.append(element('span', project.name));
    const open = element('button', 'Open project');
    open.type = 'button';
    open.addEventListener('click', () => { location.href = `/projects/${project.id}`; });
    row.append(open);
    list.append(row);
  }
  app.append(list);
}

render().catch(error => { app.replaceChildren(element('p', error.message, 'alert')); });

